//! Tests that a runtime function means the same thing no matter where it sits relative to the
//! attributes that generate the items it refers to.
//!
//! Attributes run one at a time, so while they run the crate only holds the items generated so
//! far. A runtime body elaborated at that point would bind names, methods and macro expansions
//! against an incomplete crate. Each test compiles the same program with two attributes in either
//! order and requires both to produce the same monomorphized program, in which the item
//! generated by the attribute is the one that gets called.

use crate::test_utils::get_monomorphized;
use crate::tests::{check_errors, get_program_errors};

/// Monomorphizes `src` twice, substituting `{first}` and `{second}` with the two attributes in
/// either order, and asserts that both orders result in the same program before returning it.
fn monomorphize_in_both_attribute_orders(src: &str, attributes: [&str; 2]) -> String {
    let [a, b] = attributes;
    let in_order = |first: &str, second: &str| {
        let src = src.replace("{first}", first).replace("{second}", second);
        get_monomorphized(&src).unwrap().to_string()
    };
    let program = in_order(a, b);
    assert_eq!(program, in_order(b, a), "the program depends on the order of its attributes");
    program
}

#[test]
fn function_called_by_an_attribute_binds_inherent_method_generated_by_another_attribute() {
    let src = "
    #[{first}]
    pub fn anchor1() {}

    #[{second}]
    pub fn anchor2() {}

    pub struct Amount {
        v: Field,
    }

    pub trait Check {
        fn check(self);
    }

    impl Check for Amount {
        fn check(self) {
            let _ = self.v;
        }
    }

    pub fn helper(a: Amount) {
        a.check();
    }

    comptime fn warm(_f: FunctionDefinition) {
        helper(Amount { v: 1 });
    }

    comptime fn gen_impl(_f: FunctionDefinition) -> Quoted {
        quote {
            impl crate::Amount {
                pub fn check(self) {
                    assert(self.v != 0);
                }
            }
        }
    }

    fn main(x: Field, y: Field) {
        helper(Amount { v: x });
        Amount { v: y }.check();
    }
    ";
    let program = monomorphize_in_both_attribute_orders(src, ["warm", "gen_impl"]);
    insta::assert_snapshot!(program, @r"
    fn main$f0(x$l0: Field, y$l1: Field) -> () {
        helper$f1({
            let v$l2 = x$l0;
            (v$l2)
        });;
        check$f2({
            let v$l3 = y$l1;
            (v$l3)
        });
    }
    fn helper$f1(a$l4: (Field,)) -> () {
        check$f2(a$l4);
    }
    fn check$f2(self$l5: (Field,)) -> () {
        assert((self$l5.0 != 0));
    }
    ");
}

#[test]
fn function_called_by_an_attribute_expands_macros_against_the_final_registry() {
    let src = "
    comptime mut global VALIDATORS: Quoted = quote {};

    #[{first}]
    pub fn anchor1() {}

    #[{second}]
    pub fn anchor2() {}

    comptime fn run_validators() -> Quoted {
        VALIDATORS
    }

    pub fn validate(x: Field) {
        run_validators!();
    }

    pub fn nonzero(x: Field) {
        assert(x != 0);
    }

    comptime fn warm(_f: FunctionDefinition) {
        validate(1);
    }

    comptime fn validator(_f: FunctionDefinition) {
        VALIDATORS = quote { $VALIDATORS nonzero(x); };
    }

    fn main(x: Field) {
        validate(x);
    }
    ";
    let program = monomorphize_in_both_attribute_orders(src, ["warm", "validator"]);
    insta::assert_snapshot!(program, @r"
    fn main$f0(x$l0: Field) -> () {
        validate$f1(x$l0);
    }
    fn validate$f1(x$l1: Field) -> () {
        {
            nonzero$f2(x$l1);
        };
    }
    fn nonzero$f2(x$l2: Field) -> () {
        assert((x$l2 != 0));
    }
    ");
}

