#[test]
fn generated_function_can_call_a_function_generated_by_a_later_attribute() {
    let src = "
    #[{first}]
    pub fn anchor1() {}

    #[{second}]
    pub fn anchor2() {}

    comptime fn gen_helper(_f: FunctionDefinition) -> Quoted {
        quote {
            pub fn helper(x: Field) {
                target(x);
            }
        }
    }

    comptime fn gen_target(_f: FunctionDefinition) -> Quoted {
        quote {
            pub fn target(x: Field) {
                assert(x != 0);
            }
        }
    }

    fn main(x: Field) {
        helper(x);
    }
    ";
    let program = monomorphize_in_both_attribute_orders(src, ["gen_helper", "gen_target"]);
    insta::assert_snapshot!(program, @r"
    fn main$f0(x$l0: Field) -> () {
        helper$f1(x$l0);
    }
    fn helper$f1(x$l1: Field) -> () {
        target$f2(x$l1);
    }
    fn target$f2(x$l2: Field) -> () {
        assert((x$l2 != 0));
    }
    ");
}

