#[test]
fn generated_global_is_evaluated_after_every_attribute_has_run() {
    let src = "
    comptime mut global CHECKS: u32 = 0;

    #[{first}]
    pub fn anchor1() {}

    #[{second}]
    pub fn anchor2() {}

    comptime fn gen_flag(_f: FunctionDefinition) -> Quoted {
        quote {
            pub global NEED_CHECK: bool = comptime { CHECKS > 0 };
        }
    }

    comptime fn register(_f: FunctionDefinition) {
        CHECKS += 1;
    }

    fn main(x: Field) {
        if NEED_CHECK {
            assert(x != 0);
        }
    }
    ";
    let program = monomorphize_in_both_attribute_orders(src, ["gen_flag", "register"]);
    insta::assert_snapshot!(program, @r"
    global NEED_CHECK$g0: bool = true;
    fn main$f0(x$l0: Field) -> () {
        if NEED_CHECK$g0 {
            assert((x$l0 != 0));
        }
    }
    ");
}

#[test]
fn generated_function_called_by_an_attribute_binds_inherent_method_generated_later() {
    let src = "
    #[gen_helper]
    pub fn anchor1() {}

    #[warm]
    pub fn anchor2() {}

    #[gen_impl]
    pub fn anchor3() {}

    pub struct Amount {
        v: Field,
    }

    pub trait Check {
        fn check(self);
    }

    impl Check for Amount {
        fn check(self) {
            let _ = self.v;
        }
    }

    comptime fn gen_helper(_f: FunctionDefinition) -> Quoted {
        quote {
            pub fn helper(a: crate::Amount) {
                a.check();
            }
        }
    }

    comptime fn warm(_f: FunctionDefinition) {
        helper(Amount { v: 1 });
    }

    comptime fn gen_impl(_f: FunctionDefinition) -> Quoted {
        quote {
            impl crate::Amount {
                pub fn check(self) {
                    assert(self.v != 0);
                }
            }
        }
    }

    fn main(x: Field) {
        helper(Amount { v: x });
    }
    ";
    let program = get_monomorphized(src).unwrap();
    insta::assert_snapshot!(program, @r"
    fn main$f0(x$l0: Field) -> () {
        helper$f1({
            let v$l1 = x$l0;
            (v$l1)
        });
    }
    fn helper$f1(a$l2: (Field,)) -> () {
        check$f2(a$l2);
    }
    fn check$f2(self$l3: (Field,)) -> () {
        assert((self$l3.0 != 0));
    }
    ");
}

#[test]
fn function_called_by_an_attribute_keeps_the_errors_of_the_body_the_attribute_ran() {
    // `warm` runs `helper` before `target` exists, so the program is rejected even though
    // `helper` resolves once `gen_target` has run.
    let src = "
    #[warm]
    pub fn anchor1() {}

    #[gen_target]
    pub fn anchor2() {}

    pub fn helper() {
        target();
        ^^^^^^ cannot find `target` in this scope
        ~~~~~~ not found in this scope
    }

    comptime fn warm(_f: FunctionDefinition) {
        helper();
    }

    comptime fn gen_target(_f: FunctionDefinition) -> Quoted {
        quote {
            pub fn target() {}
        }
    }

    fn main() {
        helper();
    }
    ";
    check_errors(src);
}

#[test]
fn function_called_by_an_attribute_reports_its_diagnostics_once() {
    let src = "
    #[warm]
    pub fn anchor() {}

    pub fn helper() -> Field {
        let unused = 1;
        2
    }

    comptime fn warm(_f: FunctionDefinition) {
        let _ = helper();
    }

    fn main() {
        let _ = helper();
    }
    ";
    let errors = get_program_errors(src);
    assert_eq!(errors.len(), 1, "expected a single unused variable warning, got {errors:?}");
}
